-- Read-only reconstruction from original raw pitches; historical 2025 only. No provider calls.
with raw as materialized (select game_year season,game_pk,game_date,coalesce(mlbam_batter_id,source_batter_id) batter,case when inning_topbot='Top' then source_away_team else source_home_team end team,count(*) filter(where events is not null) pa,count(*) filter(where events is not null and events not in ('walk','intent_walk','hit_by_pitch','sac_fly','sac_bunt','catcher_interf','truncated_pa')) ab,count(*) filter(where events in ('single','double','triple','home_run')) hits,count(*) filter(where events='single') singles,count(*) filter(where events='double') doubles,count(*) filter(where events='triple') triples,count(*) filter(where events='home_run') hr,count(*) filter(where events in ('walk','intent_walk')) walks,count(*) filter(where events in ('strikeout','strikeout_double_play')) strikeouts,count(*) filter(where launch_speed is not null) batted_balls,count(*) filter(where launch_speed>=95) hard_hits,count(*) filter(where launch_speed_angle=6) barrels,sum(launch_speed) filter(where launch_speed is not null) ev_sum,count(launch_speed) ev_n,count(*) pitches,count(*) filter(where events is not null)-count(distinct at_bat_number) filter(where events is not null) duplicate_terminal,count(*) filter(where events='') empty_events,count(*) filter(where inning_topbot not in ('Top','Bot') or inning_topbot is null) bad_half,count(*) filter(where mlbam_batter_id is not null and mlbam_batter_id<>source_batter_id) id_disagreement,min(ingested_at) min_ingested,max(ingested_at) max_ingested,md5(string_agg(raw_payload_digest,'|' order by at_bat_number,pitch_number,raw_payload_digest)) raw_digest from public.pick2_raw_mlb_statcast_pitches where game_year=2025 and game_type='R' and game_date between '2025-03-02' and '2025-08-30' group by 1,2,3,4,5),c as (select * from public.mlb_ml_xyear_batter_game_v1 where season=2025 and game_date between '2025-03-02' and '2025-08-30'),joined as (select coalesce(r.game_pk,c.game_pk) game_pk,coalesce(r.game_date,c.game_date) game_date,coalesce(r.team,c.team) team,coalesce(r.batter,c.batter) batter,r.game_pk is null missing_raw,c.game_pk is null missing_canonical,jsonb_build_array(r.pa,r.ab,r.hits,r.singles,r.doubles,r.triples,r.hr,r.walks,r.strikeouts,r.batted_balls,r.hard_hits,r.barrels,r.ev_sum,r.ev_n) raw_values,jsonb_build_array(c.pa,c.ab,c.hits,c.singles,c.doubles,c.triples,c.hr,c.walks,c.strikeouts,c.batted_balls,c.hard_hits,c.barrels,c.ev_sum,c.ev_n) canonical_values,r.raw_digest,r.duplicate_terminal,r.empty_events,r.bad_half,r.id_disagreement,r.pitches,r.min_ingested,r.max_ingested from raw r full join c using(season,game_pk,game_date,batter,team)) select jsonb_agg(jsonb_build_array(game_pk,game_date,team,batter,raw_values,canonical_values,raw_digest,missing_raw,missing_canonical,duplicate_terminal,empty_events,bad_half,id_disagreement,pitches,min_ingested,max_ingested) order by game_date,game_pk,team,batter) rows from joined
